library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

use work.params_pkg.all;
use work.reduce_pkg.all;
use work.types_pkg.all;

-- secure implementation of polynomial comparison for Kyber
-- based on https://tches.iacr.org/index.php/TCHES/article/view/9064/8651
entity sec_decompressed_comparison is
port (
    clk: in std_logic;
    rst: in std_logic;

    -- interface for mask conversions to enable sharing
    conversion_s_axis_tdata: out slv_array_t(1 downto 0)(95 downto 0);
    conversion_s_axis_tvalid: out std_logic;
    conversion_s_axis_tready: in std_logic;

    conversion_m_axis_tdata: in slv_array_t(1 downto 0)(95 downto 0);
    conversion_m_axis_tvalid: in std_logic;

    -- fresh randomness
    r: in std_logic_vector(7 downto 0);

    re_encrypted: out std_logic;

    -- stream of ciphertexts, first public one, that is being decrypted (u, v)
    -- followed by re-encrypted (u', v') that is split to shares
    s_axis_tdata: in slv_array_t(1 downto 0)(95 downto 0);
    -- security parameter for Kyber
    s_axis_tuser: in std_logic_vector(1 downto 0);
    s_axis_tvalid: in std_logic;
    s_axis_tready: out std_logic;

    -- indicates any coefficient did not match
    invalid: out std_logic;
    invalid_vld: out std_logic
);
end;

architecture behav of sec_decompressed_comparison is
    constant tmp_10b_lower: std_logic_vector(3328 downto 0) := "";
    constant tmp_10b_upper: std_logic_vector(3328 downto 0) := "";
    constant tmp_11b_lower: std_logic_vector(3328 downto 0) := "";
    constant tmp_11b_upper: std_logic_vector(3328 downto 0) := "";

    signal sec_and_x, sec_and_y: slv_array_t(1 downto 0)(7 downto 0);
    signal sec_and_r: slv_array_t(0 downto 0)(7 downto 0);
    signal sec_and_z: slv_array_t(1 downto 0)(7 downto 0);

    signal sec_and_vld: std_logic_vector(7 downto 0);

    signal lower_bound, upper_bound: std_logic_vector(95 downto 0);
    signal lower_bound_check, upper_bound_check: std_logic_vector(95 downto 0);

    signal bound_check_vld: std_logic;

    -- delay shares during `lower_bound_check` and `upper_bound_check` computation
    signal coeffs: std_logic_vector(95 downto 0);

    signal convert_lower_bound_check: std_logic;

    signal coeffs_counter: integer range 30 downto -1;
    signal poly_counter: integer range 3 downto -1;

    signal poly_counter_vld: std_logic;

    signal coeffs_counter_last, poly_counter_last: std_logic;

    signal invalid_shares: std_logic_vector(1 downto 0);

    signal invalid_counter: integer range 318 downto -1;

    signal invalid_counter_last: std_logic;

    -- assigning DON'T TOUCH attribute
    attribute dont_touch: string;
    attribute dont_touch of behav: architecture is "yes";

    attribute dont_touch of sec_and_x, sec_and_y: signal is "yes";
begin
    s_axis_tready <= (not re_encrypted) or ((not bound_check_vld) or (conversion_s_axis_tready and (not convert_lower_bound_check)));

    conversion_s_axis_tdata(0) <= lower_bound_check when convert_lower_bound_check = '1' else upper_bound_check;
    conversion_s_axis_tdata(1) <= coeffs;
    conversion_s_axis_tvalid <= bound_check_vld;

    sec_and: entity work.sec_and
    generic map (
        W => 8
    )
    port map (
        clk => clk,

        x => sec_and_x,
        y => sec_and_y,

        r => sec_and_r,

        z => sec_and_z
    );

    sec_and_r(0) <= r;

    sec_and_p: process(clk) is
    begin
        if rising_edge(clk) then
            for i in 0 to 1 loop
                -- first round of ANDs
                sec_and_x(i)(0) <= conversion_m_axis_tdata(i)(11);
                sec_and_y(i)(0) <= conversion_m_axis_tdata(i)(23);

                sec_and_x(i)(1) <= conversion_m_axis_tdata(i)(35);
                sec_and_y(i)(1) <= conversion_m_axis_tdata(i)(47);

                sec_and_x(i)(2) <= conversion_m_axis_tdata(i)(59);
                sec_and_y(i)(2) <= conversion_m_axis_tdata(i)(71);

                sec_and_x(i)(3) <= conversion_m_axis_tdata(i)(83);
                sec_and_y(i)(3) <= conversion_m_axis_tdata(i)(95);

                -- second round of ANDs
                sec_and_x(i)(4) <= sec_and_z(i)(0);
                sec_and_y(i)(4) <= sec_and_z(i)(1);

                sec_and_x(i)(5) <= sec_and_z(i)(2);
                sec_and_y(i)(5) <= sec_and_z(i)(3);

                -- third round of AND
                sec_and_x(i)(6) <= sec_and_z(i)(4);
                sec_and_y(i)(6) <= sec_and_z(i)(5);
            end loop;

            -- final round of AND, combining result from 8 coefficients with overall result
            sec_and_x(0)(7) <= sec_and_z(0)(6) when sec_and_vld(sec_and_vld'left - 5) = '1' else '1';
            sec_and_x(1)(7) <= sec_and_z(1)(6) when sec_and_vld(sec_and_vld'left - 5) = '1' else '0';

            sec_and_y(0)(7) <= not invalid_shares(0);
            sec_and_y(1)(7) <= invalid_shares(1);

            if rst = '1' then
                sec_and_vld <= (others => '0');
            else
                sec_and_vld <= conversion_m_axis_tvalid & sec_and_vld(sec_and_vld'left downto 1);
            end if;
        end if;
    end process;

    -- first are loaded 8 coefficients of public ciphertext followed by 8 coefficients of re-encrypted ciphertext
    re_encrypted_p: process(clk) is
    begin
        if rising_edge(clk) then
            if rst = '1' then
                re_encrypted <= '0';
            else
                if (s_axis_tvalid and s_axis_tready) = '1' then
                    re_encrypted <= not re_encrypted;
                end if;
            end if;
        end if;
    end process;

    -- find correct bounds that would result into same compression
    bounds_p: process(clk) is
        variable lower_bound_addition, upper_bound_addition: std_logic_vector(11 downto 0);
    begin
        if rising_edge(clk) then
            if (s_axis_tvalid and (not re_encrypted)) = '1' then
                for i in 0 to 7 loop
                    -- find bounds for v polynomial
                    if poly_counter_last = '1' then
                        -- 5b
                        if s_axis_tuser = "10" then
                            if unsigned(s_axis_tdata(0)(11 + 12 * i downto 7 + 12 * i)) > 12 then
                                lower_bound_addition := x"034";
                                upper_bound_addition := x"034";
                            else
                                if s_axis_tdata(0)(11 + 12 * i downto 12 * i) = (11 downto 0 => '0') then
                                    lower_bound_addition := x"034";
                                else
                                    lower_bound_addition := x"033";
                                end if;

                                upper_bound_addition := x"035";
                            end if;
                        -- 4b
                        else
                            if unsigned(s_axis_tdata(0)(11 + 12 * i downto 9 + 12 * i)) > 2 then
                                lower_bound_addition := x"068";
                                upper_bound_addition := x"068";
                            else
                                if s_axis_tdata(0)(11 + 12 * i downto 12 * i) = (11 downto 0 => '0') then
                                    lower_bound_addition := x"068";
                                else
                                    lower_bound_addition := x"067";
                                end if;

                                upper_bound_addition := x"069";
                            end if;
                        end if;
                    -- find bounds for u polynomials
                    else
                        -- 11b
                        if s_axis_tuser = "10" then
                            if tmp_11b_lower(to_integer(unsigned(s_axis_tdata(0)(11 + 12 * i downto 12 * i)))) = '1' then
                                lower_bound_addition := x"001";
                            else
                                lower_bound_addition := x"000";
                            end if;

                            if tmp_11b_upper(to_integer(unsigned(s_axis_tdata(0)(11 + 12 * i downto 12 * i)))) = '1' then
                                upper_bound_addition := x"002";
                            else
                                upper_bound_addition := x"001";
                            end if;
                        -- 10b
                        else
                            if tmp_10b_lower(to_integer(unsigned(s_axis_tdata(0)(11 + 12 * i downto 12 * i)))) = '1' then
                                lower_bound_addition := x"002";
                            else
                                lower_bound_addition := x"001";
                            end if;

                            if tmp_10b_upper(to_integer(unsigned(s_axis_tdata(0)(11 + 12 * i downto 12 * i)))) = '1' then
                                upper_bound_addition := x"003";
                            else
                                upper_bound_addition := x"002";
                            end if;
                        end if;
                    end if;

                    lower_bound(11 + 12 * i downto 12 * i) <= kyber_sub_reduce(s_axis_tdata(0)(11 + 12 * i downto 12 * i), lower_bound_addition);
                    upper_bound(11 + 12 * i downto 12 * i) <= kyber_add_reduce(s_axis_tdata(0)(11 + 12 * i downto 12 * i), upper_bound_addition);
                end loop;
            end if;
        end if;
    end process;

    -- check whether coefficient lies in bound or does not
    bounds_check_p: process(clk) is
    begin
        if rising_edge(clk) then
            if ((not bound_check_vld) or (conversion_s_axis_tready and (not convert_lower_bound_check))) = '1' then
                for i in 0 to 7 loop
                    lower_bound_check(11 + 12 * i downto 12 * i) <= kyber_sub_reduce(kyber_add_reduce(s_axis_tdata(0)(11 + 12 * i downto 12 * i), x"800"), lower_bound(11 + 12 * i downto 12 * i));
                    upper_bound_check(11 + 12 * i downto 12 * i) <= kyber_sub_reduce(s_axis_tdata(0)(11 + 12 * i downto 12 * i), upper_bound(11 + 12 * i downto 12 * i));
                end loop;

                coeffs <= s_axis_tdata(1);
            end if;

            if rst = '1' then
                bound_check_vld <= '0';
            else
                if (s_axis_tvalid and re_encrypted) = '1' then
                    bound_check_vld <= '1';
                elsif (conversion_s_axis_tready and (not convert_lower_bound_check)) = '1' then
                    bound_check_vld <= '0';
                end if;
            end if;
        end if;
    end process;

    convert_lower_bound_check_p: process(clk) is
    begin
        if rising_edge(clk) then
            if rst = '1' then
                convert_lower_bound_check <= '1';
            else
                if (conversion_s_axis_tvalid and conversion_s_axis_tready) = '1' then
                    convert_lower_bound_check <= not convert_lower_bound_check;
                end if;
            end if;
        end if;
    end process;

    coeffs_counter_last <= '1' when coeffs_counter = -1 else '0';

    coeffs_counter_p: process(clk) is
    begin
        if rising_edge(clk) then
            if rst = '1' then
                coeffs_counter <= 30;
            else
                if (s_axis_tvalid and s_axis_tready and re_encrypted) = '1' then
                    if coeffs_counter_last = '1' then
                        coeffs_counter <= 30;
                    else
                        coeffs_counter <= coeffs_counter - 1;
                    end if;
                end if;
            end if;
        end if;
    end process;

    poly_counter_last <= '1' when poly_counter = -1 else '0';

    poly_counter_p: process(clk) is
    begin
        if rising_edge(clk) then
            if rst = '1' then
                poly_counter <= 0;
                poly_counter_vld <= '0';
            else
                if (s_axis_tvalid and s_axis_tready and (not re_encrypted)) = '1' then
                    if poly_counter_vld = '0' then
                        poly_counter <= natural_for_sec_level(s_axis_tuser, 1, 2, 3);
                        poly_counter_vld <= '1';
                    elsif coeffs_counter_last = '1' then
                        if poly_counter_last = '1' then
                            poly_counter <= 0;
                            poly_counter_vld <= '0';
                        else
                            poly_counter <= poly_counter - 1;
                        end if;
                    end if;
                end if;
            end if;
        end if;
    end process;

    invalid_counter_last <= '1' when invalid_counter = -1 else '0';

    invalid_p: process(clk) is
    begin
        if rising_edge(clk) then
            invalid <= '0';
            invalid_vld <= '0';

            if rst = '1'  then
                invalid_shares <= "00";
                invalid_counter <= 0;
            else
                if (s_axis_tvalid and s_axis_tready and (not re_encrypted) and (not poly_counter_vld)) = '1' then
                    -- there are (K + 1) polynomials that need to be checked, we check 8 coefficients at a time
                    -- and there need to be two checks per coefficient (lower and upper)
                    invalid_counter <= natural_for_sec_level(s_axis_tuser, 190, 254, 318);
                elsif sec_and_vld(0) = '1' then
                    invalid_shares(0) <= not sec_and_z(0)(7);
                    invalid_shares(1) <= sec_and_z(1)(7);

                    if invalid_counter_last = '1' then
                        invalid <= invalid_shares(0) xor invalid_shares(1);
                        invalid_vld <= '1';

                        invalid_shares <= "00";
                        invalid_counter <= 0;
                    else
                        invalid_counter <= invalid_counter - 1;
                    end if;
                end if;
            end if;
        end if;
    end process;
end;
